import { MakeLogicType, actions, connect, kea, listeners, path, selectors } from 'kea'

import { FEATURE_FLAGS, OrganizationMembershipLevel } from 'lib/constants'
import { FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'
import { teamLogic } from 'scenes/teamLogic'

import { TeamPublicType, TeamType } from '~/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface firstRunEngagementEventsLogicValues {
    featureFlags: FeatureFlagsSet
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    currentTeamLoading: boolean // teamLogic
    engagementEventsCaptured: boolean
    engagementEventsDisabledReason: string | null
    offerEngagementEvents: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface firstRunEngagementEventsLogicActions {
    updateCurrentTeam: (payload: Partial<TeamType>) => Partial<TeamType> // teamLogic
    enableEngagementEvents: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface firstRunEngagementEventsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        engagementEventsCaptured: (currentTeam: TeamPublicType | TeamType | null) => boolean
        engagementEventsDisabledReason: (currentTeam: TeamPublicType | TeamType | null) => string | null
        offerEngagementEvents: (
            engagementEventsCaptured: boolean,
            engagementEventsDisabledReason: string | null,
            featureFlags: FeatureFlagsSet
        ) => boolean
    }
}

export type firstRunEngagementEventsLogicType = MakeLogicType<
    firstRunEngagementEventsLogicValues,
    firstRunEngagementEventsLogicActions,
    Record<string, any>,
    firstRunEngagementEventsLogicMeta
>

export const firstRunEngagementEventsLogic = kea<firstRunEngagementEventsLogicType>([
    path(['products', 'workflows', 'frontend', 'firstRun', 'firstRunEngagementEventsLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeam', 'currentTeamLoading'], featureFlagLogic, ['featureFlags']],
        actions: [teamLogic, ['updateCurrentTeam']],
    })),
    actions({
        enableEngagementEvents: true,
    }),
    selectors({
        engagementEventsCaptured: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): boolean =>
                !!currentTeam?.workflows_config?.capture_workflows_engagement_events,
        ],
        engagementEventsDisabledReason: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): string | null =>
                (currentTeam?.effective_membership_level ?? 0) >= OrganizationMembershipLevel.Admin
                    ? null
                    : 'Only project admins can turn on engagement events.',
        ],
        offerEngagementEvents: [
            (s) => [s.engagementEventsCaptured, s.engagementEventsDisabledReason, s.featureFlags],
            (
                engagementEventsCaptured: boolean,
                engagementEventsDisabledReason: string | null,
                featureFlags: FeatureFlagsSet
            ): boolean =>
                !!featureFlags[FEATURE_FLAGS.WORKFLOWS_FIRST_RUN] &&
                !engagementEventsCaptured &&
                !engagementEventsDisabledReason,
        ],
    }),
    listeners(({ actions, values }) => ({
        enableEngagementEvents: () => {
            if (values.offerEngagementEvents && !values.currentTeamLoading) {
                actions.updateCurrentTeam({ workflows_config: { capture_workflows_engagement_events: true } })
            }
        },
    })),
])
